window.PKG.tests = [{"id": "j7-1", "title": "7과 실전 변형 1회", "short": "1회", "school": "중3 지학사", "minutes": 30, "items": [{"n": 1, "src": "대화문", "stem": "다음 대화의 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>G: Oh, look at those cave houses! They look so unique, don't they? <span class=\"wblank\"></span><br>B: I like those balloons. They look so beautiful!<br>G: I think Türkiye is a wonderful place to visit. I hope to visit there some day.</p></div>", "opts": ["I'm glad that I live there now.", "I don't want to visit there at all.", "I wish I could not see them.", "I wish I could try living there.", "I can't wait to leave there."], "en": true, "ans": 3, "ex": "이유 ▶ 동굴 집이 독특해 보인다 → 그곳에서 살아 보고 싶다는 소망(I wish I could ~). 뒤의 '언젠가 방문하고 싶다'와도 이어진다.\n오답 ▶ ① 지금 사는 게 아니다 ②·③·⑤ 독특하다고 감탄한 말과 반대\n포인트 ▶ I wish I could + 동사원형 = ~할 수 있으면 좋겠다(지금은 못 함)", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 2, "src": "대화문", "stem": "밑줄 친 말에 담긴 의도로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>B: I got a new sled for my birthday. I can't wait to test it out.<br>G: Let me check the weather. Umm, there will be no snow for a while.<br>B: <u>I wish I could live in Alaska.</u> Then I could go sledding all day!</p></div>", "opts": ["후회 표현하기", "소망 표현하기", "허락 구하기", "충고하기", "불평하기"], "en": true, "ans": 1, "ex": "이유 ▶ I wish I could ~ = 실제로는 할 수 없지만 '~하면 좋겠다'는 소망.\n오답 ▶ ① 후회는 과거 일에 대한 아쉬움 ③ 허락 구하기는 May I ~? ④ 충고는 You'd better ~ ⑤ 눈이 안 와서 아쉽지만 표현 자체는 소망\n포인트 ▶ 소망 = I wish I could ~ / I hope to ~ / I'd love to ~", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 3, "src": "대화문", "stem": "다음 대화의 내용과 일치하는 것은?", "body": "<div class=\"wbox\"><p>B: Will it snow today?<br>G: I have no idea. Why are you waiting for snow, Taeho?<br>B: I got a new sled for my birthday. I can't wait to test it out.<br>G: Let me check the weather. Umm, there will be no snow for a while.<br>B: I wish I could live in Alaska. Then I could go sledding all day!<br>G: No kidding! Alaska is a very cold place.<br>B: I think it would be fun. I want to build a snow house and stay there on vacation.</p></div>", "opts": ["당분간 눈이 많이 올 예정이다.", "여학생은 알래스카에 살아 본 적이 있다.", "태호는 눈집에서 지내는 것이 지루할 거라고 생각한다.", "태호는 생일 선물로 새 썰매를 받았다.", "여학생은 날씨를 확인해 주지 않았다."], "en": true, "ans": 3, "ex": "이유 ▶ I got a new sled for my birthday ✔\n오답 ▶ ① there will be no snow for a while(당분간 눈 없음) ② 근거 없음 ③ I think it would be fun(재미있을 것) ⑤ Let me check the weather → 확인해 줌", "ctx": "", "pts": 5, "words": [], "kos": [["I think it would be fun. I want to build a snow house and stay there on vacation.", "내 생각에는 재미있을 것 같아. 난 눈으로 만든 집을 짓고 방학 때 그곳에서 지내고 싶어."]]}, {"n": 4, "src": "대화문", "stem": "주어진 말 다음에 이어질 대화의 순서로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>B: This is my dream house, Alice. What do you think?</p></div><div class=\"wbox\"><p><b>(A)</b> B: Yes, it can move like a car.<br><b>(B)</b> G: Oh, the house has wheels! Is it a kind of car?<br><b>(C)</b> G: So what would you do if you lived in that house?</p></div>", "opts": ["(A) − (C) − (B)", "(B) − (A) − (C)", "(B) − (C) − (A)", "(C) − (A) − (B)", "(C) − (B) − (A)"], "en": true, "ans": 1, "ex": "이유 ▶ 꿈의 집 소개 → (B) 바퀴가 있네! 차의 일종이야? → (A) 응, 차처럼 움직여 → (C) 그럼 그 집에 산다면 뭘 할 거야?\n포인트 ▶ (A)의 Yes는 (B)의 질문(Is it a kind of car?)에 대한 대답, (C)의 So는 앞 내용을 받아 묻는 말.", "ctx": "", "pts": 5, "words": [], "kos": [["This is my dream house, Alice. What do you think?", "이건 내가 꿈꾸는 집이야, Alice. 어떻게 생각해?"], ["Yes, it can move like a car.", "응, 이건 자동차처럼 움직일 수 있어."], ["So what would you do if you lived in that house?", "그래서 만약 네가 그 집에 산다면 너는 무엇을 할 거니?"]]}, {"n": 5, "src": "대화문", "stem": "다음 대화의 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>A: What would you do if you became a millionaire?<br>B: <span class=\"wblank\"></span></p></div>", "opts": ["I would build my own house.", "I built my own house last year.", "I will be a millionaire someday.", "Yes, I would.", "I wish I were a millionaire."], "en": true, "ans": 0, "ex": "이유 ▶ What would you do if ~? (가정) → I would ~ 로 대답.\n오답 ▶ ② 과거 사실 ③ 무엇을 할지에 대한 답이 아님 ④ 의문사 의문문에 Yes ❌ ⑤ 소망일 뿐 무엇을 할지 답하지 않음\n포인트 ▶ 상상해서 묻기 What would you do if ~? → 답 I would ~", "ctx": "", "pts": 5, "words": [], "kos": [["What would you do if you became a millionaire, Juwon?", "만약 네가 백만장자가 된다면 너는 무엇을 할 거니, 주원아?"]]}, {"n": 6, "src": "대화문", "stem": "다음 중 짝지어진 대화가 <u>어색한</u> 것은?", "body": "", "opts": ["A: I wish I could fly. — B: Me too. It would be fun.", "A: Does anybody live in the upside-down house? — B: No, it would not be easy to live there.", "A: What would you do if you lived in a tree house? — B: I lived there last year.", "A: Which country do you want to visit? — B: In my case, I want to visit Spain.", "A: Living in a jungle would be exciting. Don't you think so? — B: But there are dangerous animals there."], "en": true, "ans": 2, "ex": "이유 ▶ 나무 집에 산다면 '무엇을 할지' 물었는데 작년에 살았다는 과거 사실로 답함 → 어색. (예: I would watch the birds.)\n오답 ▶ ① 소망에 동의 ✔ ② 살기 쉽지 않을 것 ✔ ④ 나라 질문 → 스페인 ✔ ⑤ 반대 의견 제시 ✔", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 7, "src": "본문", "stem": "다음 글 뒤에 이어질 내용으로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>Different people live in different houses. Some use ladders to enter their houses. Others live in houses on the water. And others share their houses with many people. Imagine you live in one of these houses. How would that change your life?</p></div>", "opts": ["사다리를 안전하게 사용하는 방법", "물 위에 집을 짓는 공사 과정", "대가족이 함께 사는 것의 단점", "도시와 시골 집값의 차이", "세계 여러 지역의 독특한 집에서 사는 삶을 상상해 보는 글"], "en": true, "ans": 4, "ex": "이유 ▶ 여러 종류의 집을 소개하고 '그중 하나에 산다면 삶이 어떻게 바뀔지 상상해 보라' → 이어서 각 집에 사는 모습을 상상(If I lived in ~).\n오답 ▶ ①·②·③·④ 집의 예일 뿐이거나 언급 없음", "ctx": "", "pts": 5, "words": [], "kos": [["Different people live in different houses.", "다양한 사람들이 다양한 집에서 삽니다."], ["Some use ladders to enter their houses.", "몇몇 사람들은 집에 들어가기 위해 사다리를 이용합니다."], ["Others live in houses on the water.", "다른 사람들은 물 위에 있는 집에 삽니다."], ["And others share their houses with many people.", "그리고 또 다른 사람들은 많은 사람과 함께 집을 공유합니다."], ["Imagine you live in one of these houses.", "여러분이 이 집들 중 하나에 산다고 상상해 보세요."], ["How would that change your life?", "여러분의 삶은 어떻게 바뀔까요?"]]}, {"n": 8, "src": "본문", "stem": "다음 글의 내용과 일치하지 <u>않는</u> 것은?", "body": "<div class=\"wbox\"><p>If I lived in a pueblo, I would climb up a ladder to enter my house. There's a hidden opening on top of the house. If unwelcome visitors appeared, I would pull the ladder up to stop them from entering. The thick walls are made of earth, straw, and water. They would keep me cool in summer and warm in winter. The house has a flat roof. I would sometimes sleep up on the roof under the moon and stars.</p></div>", "opts": ["There is a hidden opening on top of the house.", "The walls of the house are made of wood and stone.", "People use a ladder to enter the house.", "The thick walls keep the house cool in summer.", "The house has a flat roof."], "en": true, "ans": 1, "ex": "이유 ▶ The thick walls are made of earth, straw, and water(흙, 지푸라기, 물) → 나무와 돌이 아님.\n오답 ▶ ① hidden opening on top ✔ ③ climb up a ladder to enter ✔ ④ keep me cool in summer ✔ ⑤ a flat roof ✔", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in a pueblo, I would climb up a ladder to enter my house.", "만약 내가 푸에블로에 산다면, 나는 집에 들어가기 위해 사다리를 오를 것이다."], ["There's a hidden opening on top of the house.", "집 꼭대기에는 숨겨진 구멍이 있다."], ["If unwelcome visitors appeared, I would pull the ladder up to stop them from entering.", "만약 반갑지 않은 방문객이 나타난다면 나는 사다리를 끌어 올려 그들이 들어오지 못하게 할 것이다."], ["The thick walls are made of earth, straw, and water.", "두꺼운 벽은 흙, 지푸라기, 물로 만들어져 있다."], ["They would keep me cool in summer and warm in winter.", "그것들은 여름에는 시원하게, 겨울에는 따뜻하게 유지해 줄 것이다."], ["The house has a flat roof.", "집에는 평평한 지붕이 있다."], ["I would sometimes sleep up on the roof under the moon and stars.", "때때로 나는 달과 별들 아래의 지붕 위에서 잠을 잘 것이다."]]}, {"n": 9, "src": "본문", "stem": "다음 글의 밑줄 친 부분 중, 어법상 <u>틀린</u> 것은?", "body": "<div class=\"wbox\"><p>If I ①<u>lived</u> in a pueblo, I would climb up a ladder ②<u>to enter</u> my house. If unwelcome visitors appeared, I would pull the ladder up to stop them from ③<u>enter</u>. The thick walls ④<u>are made</u> of earth, straw, and water. They would keep me ⑤<u>cool</u> in summer and warm in winter.</p></div>", "opts": ["lived", "to enter", "enter", "are made", "cool"], "en": true, "ans": 2, "ex": "이유 ▶ stop A from -ing(A가 ~하지 못하게 하다) → from 뒤에 동명사 entering.\n오답 ▶ ① 가정법 과거(If + 과거형, would) ✔ ② 목적(~하기 위해) ✔ ③ 벽이 '만들어진' 수동 ✔ ⑤ keep + 목적어 + 형용사 ✔\n포인트 ▶ 전치사 뒤에는 동명사!", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in a pueblo, I would climb up a ladder to enter my house.", "만약 내가 푸에블로에 산다면, 나는 집에 들어가기 위해 사다리를 오를 것이다."], ["If unwelcome visitors appeared, I would pull the ladder up to stop them from entering.", "만약 반갑지 않은 방문객이 나타난다면 나는 사다리를 끌어 올려 그들이 들어오지 못하게 할 것이다."], ["The thick walls are made of earth, straw, and water.", "두꺼운 벽은 흙, 지푸라기, 물로 만들어져 있다."], ["They would keep me cool in summer and warm in winter.", "그것들은 여름에는 시원하게, 겨울에는 따뜻하게 유지해 줄 것이다."]]}, {"n": 10, "src": "본문", "stem": "다음 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>Venice is known as the \"<span class=\"wblank\"></span> city.\" In Venice, there are many colorful houses on the water.</p></div>", "opts": ["sinking", "frozen", "hidden", "moving", "floating"], "en": true, "ans": 4, "ex": "이유 ▶ 물 위에 집들이 있는 베니스 = '떠 있는' 도시(floating city).\n오답 ▶ ① 가라앉는 ② 얼어붙은 ③ 숨겨진 ④ 움직이는 — 본문 표현이 아님", "ctx": "", "pts": 5, "words": [], "kos": [["Venice is known as the \"floating city.\"", "베니스는 '떠 있는 도시'로 알려져 있다."], ["In Venice, there are many colorful houses on the water.", "베니스에는 물 위에 있는 색색의 건물들이 많다."]]}, {"n": 11, "src": "본문", "stem": "다음 글의 밑줄 친 부분 중, 문맥상 낱말의 쓰임이 적절하지 <u>않은</u> 것은?", "body": "<div class=\"wbox\"><p>At high tide, the water from the Adriatic Sea often ①<u>rises</u> and leaves the streets ②<u>full</u> of water. However, I would be able to walk around the town through the ③<u>raised</u> walkways. The old Venetians decided to live there to keep themselves ④<u>safe</u> from invaders. But it was ⑤<u>easy</u> for them to build their homes on this swampy surface. So they installed more than 10 million wooden poles in the ground.</p></div>", "opts": ["rises", "full", "raised", "safe", "easy"], "en": true, "ans": 4, "ex": "이유 ▶ But(하지만) + So 나무 기둥을 천만 개 이상 설치했다 → 습지 위에 집 짓기가 '쉽지 않았다' → not easy (difficult).\n오답 ▶ ① 물이 '불어나' ② 거리를 물로 '가득' ③ '높이 올린' 통로 ④ 침략자로부터 '안전하게'", "ctx": "", "pts": 5, "words": [], "kos": [["At high tide, the water from the Adriatic Sea often rises and leaves the streets full of water.", "조수가 높을 때에는 아드리아해의 물이 자주 불어나 거리를 물로 가득 차게 한다."], ["However, I would be able to walk around the town through the raised walkways.", "그러나 나는 높이 올린 통로로 도심 주변을 걸어 다닐 수 있을 것이다."], ["The old Venetians decided to live there to keep themselves safe from invaders.", "옛 베니스인들은 침략자들로부터 자신들을 안전하게 지키기 위해 그곳에 살기로 결정했다."], ["But it was not easy for them to build their homes on this swampy surface.", "하지만 그들이 이 습지 위에 집을 짓는 것은 쉽지가 않았다."], ["So they installed more than 10 million wooden poles in the ground.", "그래서 그들은 땅에 천만 개 이상의 나무 기둥들을 설치했다."]]}, {"n": 12, "src": "본문", "stem": "Why did the old Venetians decide to live on the water?", "body": "<div class=\"wbox\"><p>Venice is known as the \"floating city.\" In Venice, there are many colorful houses on the water. You may wonder how and why they built the houses on the water. The old Venetians decided to live there to keep themselves safe from invaders. But it was not easy for them to build their homes on this swampy surface. So they installed more than 10 million wooden poles in the ground. It is these wooden poles that support Venice to this day.</p></div>", "opts": ["To catch more fish in the sea.", "Because the land was too expensive.", "Because they wanted to travel by gondola.", "To keep themselves safe from invaders.", "Because they liked colorful houses."], "en": true, "ans": 3, "ex": "이유 ▶ The old Venetians decided to live there to keep themselves safe from invaders ✔\n오답 ▶ ①·②·③·⑤ 본문에 없는 이유", "ctx": "", "pts": 5, "words": [], "kos": [["Venice is known as the \"floating city.\"", "베니스는 '떠 있는 도시'로 알려져 있다."], ["In Venice, there are many colorful houses on the water.", "베니스에는 물 위에 있는 색색의 건물들이 많다."], ["You may wonder how and why they built the houses on the water.", "여러분은 어떻게 그리고 왜 그들이 물 위에 집을 지었는지 궁금할 것이다."], ["The old Venetians decided to live there to keep themselves safe from invaders.", "옛 베니스인들은 침략자들로부터 자신들을 안전하게 지키기 위해 그곳에 살기로 결정했다."], ["But it was not easy for them to build their homes on this swampy surface.", "하지만 그들이 이 습지 위에 집을 짓는 것은 쉽지가 않았다."], ["So they installed more than 10 million wooden poles in the ground.", "그래서 그들은 땅에 천만 개 이상의 나무 기둥들을 설치했다."], ["It is these wooden poles that support Venice to this day.", "지금까지 베니스를 지탱해 주고 있는 것은 바로 이 나무 기둥들이다."]]}, {"n": 13, "src": "본문", "stem": "다음 글의 내용과 일치하는 것은?", "body": "<div class=\"wbox\"><p>If I lived in a tulou, a huge round house in Fujian, China, I would always have friends at home to play with. I would sometimes hear my neighbor calling me to come over for tea or dinner. In a tulou, there are usually three to five floors. The first floor is used for cooking and eating. And people store food and tools on the second floor. Do you wonder where I would sleep? My bedroom would be on the third or fourth floor.</p></div>", "opts": ["2층에는 주로 침실이 있다.", "토루는 보통 6층 이상이다.", "1층은 요리하고 식사하는 데 쓰인다.", "글쓴이의 침실은 1층에 있을 것이다.", "이웃과는 거의 왕래하지 않는다."], "en": true, "ans": 2, "ex": "이유 ▶ The first floor is used for cooking and eating ✔\n오답 ▶ ① 2층은 식량·도구 보관 ② three to five floors ④ third or fourth floor ⑤ 이웃이 차·저녁 먹으러 오라고 부름", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in a tulou, a huge round house in Fujian, China, I would always have friends at home to play with.", "만약 내가 거대하고 둥그런 집인 중국 푸젠의 토루에 산다면, 나는 항상 집에 함께 놀 친구들이 있을 것이다."], ["I would sometimes hear my neighbor calling me to come over for tea or dinner.", "때때로 나의 이웃이 차를 마시거나 저녁 식사를 하러 들르라고 나를 부르는 소리를 듣게 될 것이다."], ["In a tulou, there are usually three to five floors.", "토루는 대개 3층에서 5층으로 되어 있다."], ["The first floor is used for cooking and eating.", "1층은 요리하고 식사하는 데에 사용된다."], ["And people store food and tools on the second floor.", "그리고 사람들은 2층에 식량과 도구를 보관한다."], ["Do you wonder where I would sleep?", "내가 어디에서 잠을 잘지 궁금한가?"], ["My bedroom would be on the third or fourth floor.", "내 침실은 3층이나 4층에 있을 것이다."]]}, {"n": 14, "src": "본문", "stem": "다음 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>A tulou is like a <span class=\"wblank\"></span>. The people living in a tulou mostly have the same family name. Some large tulou can house up to 50 families. They work together and share many things.</p></div>", "opts": ["village", "castle", "school", "market", "museum"], "en": true, "ans": 0, "ex": "이유 ▶ 같은 성을 가진 사람들, 50가구까지, 함께 일하고 나눔 → '마을'과 같다.\n오답 ▶ 다른 장소들은 뒤 설명과 이어지지 않음", "ctx": "", "pts": 5, "words": [], "kos": [["The people living in a tulou mostly have the same family name.", "토루에 사는 사람들은 대부분 같은 성(姓)을 가지고 있다."], ["Some large tulou can house up to 50 families.", "몇몇 큰 토루는 50가구까지 수용할 수 있다."], ["They work together and share many things.", "그들은 함께 일하고 많은 것을 공유한다."]]}, {"n": 15, "src": "문법", "stem": "다음 빈칸에 들어갈 말로 알맞은 것은?", "body": "<div class=\"wbox\"><p>If I <span class=\"wblank\"></span> a tulou, I would always have friends at home to play with.</p></div>", "opts": ["live in", "lived in", "will live in", "living in", "to live in"], "en": true, "ans": 1, "ex": "이유 ▶ 주절이 would + 동사원형 → 가정법 과거: If + 주어 + 동사의 과거형.\n오답 ▶ ① 현재형(직설법 조건) ③ 조건절에 will ❌ ④·⑤ 동사 자리가 아님\n포인트 ▶ If + 과거형, 주어 + would/could + 동사원형 = 현재 사실의 반대", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in a tulou, a huge round house in Fujian, China, I would always have friends at home to play with.", "만약 내가 거대하고 둥그런 집인 중국 푸젠의 토루에 산다면, 나는 항상 집에 함께 놀 친구들이 있을 것이다."]]}, {"n": 16, "src": "문법", "stem": "다음 문장과 의미가 같은 것은?", "body": "<div class=\"wbox\"><p>As I don't live in Venice, I can't take a gondola to school.</p></div>", "opts": ["If I lived in Venice, I could take a gondola to school.", "If I live in Venice, I can take a gondola to school.", "If I didn't live in Venice, I couldn't take a gondola to school.", "If I lived in Venice, I couldn't take a gondola to school.", "Though I live in Venice, I can't take a gondola to school."], "en": true, "ans": 0, "ex": "이유 ▶ 직설법(현재 부정) → 가정법 과거(긍정): don't live → lived, can't → could.\n오답 ▶ ② 가정법이 아님 ③ 긍정·부정이 반대 ④ 주절이 반대 ⑤ 실제로 산다는 뜻\n포인트 ▶ 직설 ↔ 가정: 시제는 한 칸 과거로, 긍정 ↔ 부정은 뒤집기", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in Venice, I would take a gondola to school.", "만약 내가 베니스에 산다면, 곤돌라를 타고 학교에 갈 것이다."]]}, {"n": 17, "src": "문법", "stem": "다음 빈칸에 들어갈 말로 알맞은 것은?", "body": "<div class=\"wbox\"><p>Living together in one building keeps them <span class=\"wblank\"></span>.</p></div>", "opts": ["safely", "safety", "to safe", "safe", "be safe"], "en": true, "ans": 3, "ex": "이유 ▶ keep + 목적어 + 형용사(목적격 보어) = ~을 …한 상태로 유지하다 → safe.\n오답 ▶ ① 부사는 보어 자리에 못 옴 ② 명사(안전)는 them과 같은 대상이 아님 ③·⑤ 형태 오류\n포인트 ▶ keep/make + 목적어 + 형용사 (부사 ❌)", "ctx": "", "pts": 5, "words": [], "kos": [["Living together in one building keeps them safe.", "한 건물에 함께 사는 것은 그들을 안전하게 지켜 준다."]]}, {"n": 18, "src": "문법", "stem": "다음 밑줄 친 부분과 쓰임이 같은 것은?", "body": "<div class=\"wbox\"><p><u>It</u> is these wooden poles <u>that</u> support Venice to this day.</p></div>", "opts": ["It is true that he is honest.", "It is interesting to see the house.", "It was Tom that broke the window yesterday.", "It is so cold that I want to stay home.", "It is a pity that she left early."], "en": true, "ans": 2, "ex": "이유 ▶ It is[was] + 강조할 말 + that ~: 'Tom'을 강조(어제 창문을 깬 사람은 바로 Tom이었다).\n오답 ▶ ①·⑤ 가주어 it, 진주어 that절 ② 가주어 it, 진주어 to부정사 ④ 날씨 it + so ~ that(너무 ~해서 …하다)\n포인트 ▶ It is ~ that에서 It is와 that을 지워도 문장이 완전하면 강조 구문(These wooden poles support Venice.)", "ctx": "", "pts": 5, "words": [], "kos": [["It is these wooden poles that support Venice to this day.", "지금까지 베니스를 지탱해 주고 있는 것은 바로 이 나무 기둥들이다."]]}, {"n": 19, "src": "본문", "stem": "주어진 문장 다음에 이어질 글의 순서로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>In a tulou, there are usually three to five floors.</p></div><div class=\"wbox\"><p><b>(A)</b> The first floor is used for cooking and eating.<br><b>(B)</b> Do you wonder where I would sleep? My bedroom would be on the third or fourth floor.<br><b>(C)</b> And people store food and tools on the second floor.</p></div>", "opts": ["(A) − (C) − (B)", "(B) − (A) − (C)", "(B) − (C) − (A)", "(C) − (A) − (B)", "(C) − (B) − (A)"], "en": true, "ans": 0, "ex": "이유 ▶ 3~5층 → (A) 1층: 요리·식사 → (C) And 2층: 식량·도구 보관 → (B) 내 침실은 3·4층.\n포인트 ▶ 층 순서(1층 → 2층 → 3·4층)와 연결어 And", "ctx": "", "pts": 5, "words": [], "kos": [["In a tulou, there are usually three to five floors.", "토루는 대개 3층에서 5층으로 되어 있다."], ["The first floor is used for cooking and eating.", "1층은 요리하고 식사하는 데에 사용된다."], ["Do you wonder where I would sleep?", "내가 어디에서 잠을 잘지 궁금한가?"], ["My bedroom would be on the third or fourth floor.", "내 침실은 3층이나 4층에 있을 것이다."], ["And people store food and tools on the second floor.", "그리고 사람들은 2층에 식량과 도구를 보관한다."]]}, {"n": 20, "src": "본문", "stem": "7과 본문 전체의 제목으로 가장 알맞은 것은?", "body": "", "opts": ["How to Build a House on Water", "The Long History of Venice", "Why Big Families Should Live Together", "Dangerous Animals in the Jungle", "Homes Around the World: Imagining Life in Them"], "en": true, "ans": 4, "ex": "이유 ▶ 푸에블로·베니스·토루 등 세계의 다양한 집을 소개하며 그곳에 산다면 어떨지 상상하는 글.\n오답 ▶ ①·②·③ 한 부분만 다룸 ④ 대화문 내용", "ctx": "", "pts": 5, "words": [], "kos": []}]}, {"id": "j7-2", "title": "7과 실전 변형 2회", "short": "2회", "school": "중3 지학사", "minutes": 30, "items": [{"n": 1, "src": "대화문", "stem": "다음 대화의 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>G: Look. The house in this picture is upside down.<br>B: That's interesting. Does anybody live there?<br>G: No, it would not be easy to live there because <span class=\"wblank\"></span>.<br>B: Really? But I want to try living there.</p></div>", "opts": ["the inside is also upside down", "it is too far from the city", "nobody wants to see it", "it is covered with mirrors", "the house has wheels"], "en": true, "ans": 0, "ex": "이유 ▶ 거꾸로 된 집에 살기 쉽지 않은 이유 → 안쪽도 거꾸로 되어 있어서.\n오답 ▶ ②·③ 근거 없음 ④ 거울 집 ⑤ 바퀴 달린 집 — 다른 대화의 집", "ctx": "", "pts": 5, "words": [], "kos": [["Look. The house in this picture is upside down.", "봐. 이 사진 속의 집은 거꾸로 되어 있어."], ["Really? But I want to try living there.", "정말? 하지만 나는 그곳에서 살아 보고 싶어."]]}, {"n": 2, "src": "대화문", "stem": "다음 대화의 내용과 일치하는 것은?", "body": "<div class=\"wbox\"><p>G: Dohun, we need to start our project on our dream country to visit.<br>B: That's right. Which country do you want to visit, Emma?<br>G: In my case, I want to visit Spain.<br>B: What would you do if you visited Spain?<br>G: I'm interested in buildings. So I would go see La Sagrada Familia.<br>B: Isn't that the church Antoni Gaudí designed?<br>G: Yes, it is. It would be interesting to see how his design was inspired by nature.<br>B: Hmm... How about Gaudí and Spain as the title for our project?<br>G: I love it!</p></div>", "opts": ["Dohun designed La Sagrada Familia.", "Emma wants to visit Italy.", "Emma is interested in buildings.", "They have already finished their project.", "Emma suggested the title for the project."], "en": true, "ans": 2, "ex": "이유 ▶ I'm interested in buildings(Emma) ✔\n오답 ▶ ① 설계자는 Gaudí ② 스페인 ④ 이제 시작해야 함(need to start) ⑤ 제목은 Dohun이 제안(How about ~?)", "ctx": "", "pts": 5, "words": [], "kos": [["Dohun, we need to start our project on our dream country to visit.", "도훈아, 우리가 가 보기를 꿈꾸는 나라에 대한 과제를 시작해야 해."], ["Yes, it is. It would be interesting to see how his design was inspired by nature.", "응, 맞아. 그의 디자인이 어떻게 자연으로부터 영감을 받았는지 보는 것은 재미있을 거야."], ["Hmm... How about Gaudí and Spain as the title for our project?", "음…. 'Gaudí와 스페인'을 우리 과제의 제목으로 하면 어때?"]]}, {"n": 3, "src": "대화문", "stem": "다음 대화의 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>Claire: Then where would you sleep? In a cave?<br>Jinho: No, I would stay in a tree house. Then <span class=\"wblank\"></span><br>Claire: That makes sense.</p></div>", "opts": ["I would be in danger every night.", "I would go back home to sleep.", "I would be safe from dangerous animals.", "I could live in a cave instead.", "animals could easily come into my house."], "en": true, "ans": 2, "ex": "이유 ▶ 위험한 동물이 있는 정글 → 나무 위 집 = 동물로부터 안전. That makes sense(일리가 있네)와 연결.\n오답 ▶ ①·⑤ 오히려 위험해짐 ② 정글에서 지내는 상상과 맞지 않음 ④ 동굴이 아니라고 했다", "ctx": "", "pts": 5, "words": [], "kos": [["Then where would you sleep? In a cave?", "그러면 잠은 어디서 잘 거야? 동굴 안에서?"]]}, {"n": 4, "src": "대화문", "stem": "다음 문장과 의미가 가장 가까운 것은?", "body": "<div class=\"wbox\"><p>I wish I could live in a snow house.</p></div>", "opts": ["I'd love to live in a snow house.", "I'm sorry that I lived in a snow house.", "I don't want to live in a snow house.", "I used to live in a snow house.", "I'm sure I will live in a snow house."], "en": true, "ans": 0, "ex": "이유 ▶ 소망 I wish I could ~ = I'd love to ~ / I hope to ~\n오답 ▶ ② 과거 후회 ③ 반대 ④ 과거 습관 ⑤ 확신", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 5, "src": "대화문", "stem": "다음 대화를 통해 알 수 있는 것은?", "body": "<div class=\"wbox\"><p>G: What kind of house would you build?<br>B: I would build a house that is completely covered with mirrors.<br>G: Why?<br>B: The mirrors would make the house almost invisible. Wouldn't that be cool?<br>G: That would be cool!</p></div>", "opts": ["The boy already lives in a mirror house.", "The mirrors would make the house hard to see.", "The girl thinks the house would look strange.", "The boy wants to build a house with wheels.", "The house would be covered with glass windows only."], "en": true, "ans": 1, "ex": "이유 ▶ make the house almost invisible = 집을 거의 보이지 않게 만들다 = 보기 어렵게.\n오답 ▶ ① 가정(would build) ③ That would be cool(멋지겠다) ④ 바퀴 집은 다른 대화 ⑤ 거울로 완전히 덮인 집\n어휘 ▶ invisible 보이지 않는", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 6, "src": "대화문", "stem": "다음 대화의 ①~⑤ 중 흐름과 관계없는 말은?", "body": "<div class=\"wbox\"><p>Jinho: I think living in a jungle would be really exciting. Don't you think so?<br>① Claire: But there are some dangerous animals in the jungle, Jinho.<br>② Jinho: I know. But the jungle is full of adventure. I wish I could live there.<br>③ Claire: What would you do if you lived in the jungle?<br>④ Jinho: I would explore it. I'm afraid of exploring new places, though.<br>⑤ Claire: Then where would you sleep? In a cave?</p></div>", "opts": ["①번", "②번", "③번", "④번", "⑤번"], "en": false, "ans": 3, "ex": "이유 ▶ 정글은 모험으로 가득하고 탐험하겠다고 해 놓고, 새로운 곳을 탐험하는 게 무섭다는 말은 흐름과 반대.\n포인트 ▶ 원래 대화: I would explore it. Maybe I could make some animal friends.", "ctx": "", "pts": 5, "words": [], "kos": [["I think living in a jungle would be really exciting. Don't you think so?", "내 생각에 정글에 사는 것은 정말 재미있을 것 같아. 그렇게 생각하지 않니?"], ["But there are some dangerous animals in the jungle, Jinho.", "하지만 정글에는 몇몇 위험한 동물들이 있어, 진호야."], ["Wow, I wish I could try living there!", "와, 저곳에서 살아 봤으면 좋겠어!"], ["What would you do if you lived in the jungle?", "만약 네가 정글에서 산다면 너는 무엇을 할 거니?"], ["Then where would you sleep? In a cave?", "그러면 잠은 어디서 잘 거야? 동굴 안에서?"]]}, {"n": 7, "src": "본문", "stem": "(A), (B), (C)에 들어갈 말로 바르게 짝지은 것은?", "body": "<div class=\"wbox\"><p>Different people live in different houses. <b>(A)</b> <span class=\"wblank\"></span> use ladders to enter their houses. <b>(B)</b> <span class=\"wblank\"></span> live in houses on the water. And <b>(C)</b> <span class=\"wblank\"></span> share their houses with many people.</p></div><div class=\"wcols\">선택지 순서: (A) / (B) / (C)</div>", "opts": ["One / The other / others", "Some / The other / another", "Others / Some / the others", "Some / Another / the other", "Some / Others / others"], "en": true, "ans": 4, "ex": "이유 ▶ 여러 사람 중 '몇몇은(Some) ~, 다른 사람들은(Others) ~, 또 다른 사람들은(others) ~' — 정해지지 않은 여럿을 나누어 말할 때.\n오답 ▶ One / the other는 둘 중 하나와 나머지 하나 / another·the other는 단수 / the others는 나머지 전부\n포인트 ▶ Some ~, Others[others] ~ (여럿을 나열)", "ctx": "", "pts": 5, "words": [], "kos": [["And others share their houses with many people.", "그리고 또 다른 사람들은 많은 사람과 함께 집을 공유합니다."]]}, {"n": 8, "src": "본문", "stem": "다음 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>If I lived in a pueblo, I would climb up a ladder to enter my house. There's a hidden opening on top of the house. If unwelcome visitors appeared, I would pull the ladder up to <span class=\"wblank\"></span>.</p></div>", "opts": ["help them climb up easily", "invite them inside", "stop them from entering", "sleep on the roof", "fix the hidden opening"], "en": true, "ans": 2, "ex": "이유 ▶ 반갑지 않은 방문객(unwelcome visitors) → 사다리를 끌어 올려 '들어오지 못하게'.\n오답 ▶ ①·② 반대 ④ 지붕에서 자는 것은 다른 내용 ⑤ 근거 없음", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in a pueblo, I would climb up a ladder to enter my house.", "만약 내가 푸에블로에 산다면, 나는 집에 들어가기 위해 사다리를 오를 것이다."], ["There's a hidden opening on top of the house.", "집 꼭대기에는 숨겨진 구멍이 있다."], ["If unwelcome visitors appeared, I would pull the ladder up.", "만약 반갑지 않은 방문객이 나타난다면, 나는 사다리를 끌어 올릴 것이다."]]}, {"n": 9, "src": "본문", "stem": "다음 글의 밑줄 친 부분 중, 어법상 <u>틀린</u> 것은?", "body": "<div class=\"wbox\"><p>If I ①<u>lived</u> in Venice, I would take a gondola to school every morning. At high tide, the water often rises and leaves the streets ②<u>full</u> of water. You may wonder how and why they ③<u>built</u> the houses on the water. The old Venetians decided ④<u>living</u> there to keep themselves safe from invaders. It is these wooden poles that ⑤<u>support</u> Venice to this day.</p></div>", "opts": ["lived", "full", "built", "living", "support"], "en": true, "ans": 3, "ex": "이유 ▶ decide는 to부정사를 목적어로 → decided to live.\n오답 ▶ ① 가정법 과거 ✔ ② leave + 목적어 + 형용사(~을 …한 상태로 두다) ✔ ③ 과거의 일 ✔ ⑤ 강조되는 말 these wooden poles(복수) → support ✔\n포인트 ▶ decide / want / hope / plan + to부정사", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in Venice, I would take a gondola to school every morning.", "만약 내가 베니스에 산다면, 나는 매일 아침 곤돌라를 타고 학교에 갈 것이다."], ["At high tide, the water from the Adriatic Sea often rises and leaves the streets full of water.", "조수가 높을 때에는 아드리아해의 물이 자주 불어나 거리를 물로 가득 차게 한다."], ["You may wonder how and why they built the houses on the water.", "여러분은 어떻게 그리고 왜 그들이 물 위에 집을 지었는지 궁금할 것이다."], ["The old Venetians decided to live there to keep themselves safe from invaders.", "옛 베니스인들은 침략자들로부터 자신들을 안전하게 지키기 위해 그곳에 살기로 결정했다."], ["It is these wooden poles that support Venice to this day.", "지금까지 베니스를 지탱해 주고 있는 것은 바로 이 나무 기둥들이다."]]}, {"n": 10, "src": "본문", "stem": "다음 글의 내용과 일치하지 <u>않는</u> 것은?", "body": "<div class=\"wbox\"><p>If I lived in Venice, I would take a gondola to school every morning. Venice has 118 small islands. On weekends, I would travel from island to island by a vaporetto, a water bus. At high tide, the water from the Adriatic Sea often rises and leaves the streets full of water. However, I would be able to walk around the town through the raised walkways. Venice is known as the \"floating city.\" In Venice, there are many colorful houses on the water. You may wonder how and why they built the houses on the water. The old Venetians decided to live there to keep themselves safe from invaders. But it was not easy for them to build their homes on this swampy surface. So they installed more than 10 million wooden poles in the ground. It is these wooden poles that support Venice to this day.</p></div>", "opts": ["A vaporetto is a kind of water bus.", "Venice consists of more than 200 small islands.", "The streets are sometimes filled with seawater.", "There are raised walkways in the town.", "More than 10 million wooden poles were installed."], "en": true, "ans": 1, "ex": "이유 ▶ Venice has 118 small islands → 200개 이상이 아님.\n오답 ▶ ① a vaporetto, a water bus ✔ ③ leaves the streets full of water ✔ ④ raised walkways ✔ ⑤ more than 10 million wooden poles ✔\n어휘 ▶ consist of ~으로 이루어지다", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in Venice, I would take a gondola to school every morning.", "만약 내가 베니스에 산다면, 나는 매일 아침 곤돌라를 타고 학교에 갈 것이다."], ["Venice has 118 small islands.", "베니스에는 118개의 작은 섬들이 있다."], ["On weekends, I would travel from island to island by a vaporetto, a water bus.", "주말마다 나는 수상 버스인 바포레토를 타고 이 섬 저 섬을 여행할 것이다."], ["At high tide, the water from the Adriatic Sea often rises and leaves the streets full of water.", "조수가 높을 때에는 아드리아해의 물이 자주 불어나 거리를 물로 가득 차게 한다."], ["However, I would be able to walk around the town through the raised walkways.", "그러나 나는 높이 올린 통로로 도심 주변을 걸어 다닐 수 있을 것이다."], ["Venice is known as the \"floating city.\"", "베니스는 '떠 있는 도시'로 알려져 있다."], ["In Venice, there are many colorful houses on the water.", "베니스에는 물 위에 있는 색색의 건물들이 많다."], ["You may wonder how and why they built the houses on the water.", "여러분은 어떻게 그리고 왜 그들이 물 위에 집을 지었는지 궁금할 것이다."], ["The old Venetians decided to live there to keep themselves safe from invaders.", "옛 베니스인들은 침략자들로부터 자신들을 안전하게 지키기 위해 그곳에 살기로 결정했다."], ["But it was not easy for them to build their homes on this swampy surface.", "하지만 그들이 이 습지 위에 집을 짓는 것은 쉽지가 않았다."], ["So they installed more than 10 million wooden poles in the ground.", "그래서 그들은 땅에 천만 개 이상의 나무 기둥들을 설치했다."], ["It is these wooden poles that support Venice to this day.", "지금까지 베니스를 지탱해 주고 있는 것은 바로 이 나무 기둥들이다."]]}, {"n": 11, "src": "본문", "stem": "주어진 문장 다음에 이어질 글의 순서로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>You may wonder how and why they built the houses on the water.</p></div><div class=\"wbox\"><p><b>(A)</b> So they installed more than 10 million wooden poles in the ground. It is these wooden poles that support Venice to this day.<br><b>(B)</b> But it was not easy for them to build their homes on this swampy surface.<br><b>(C)</b> The old Venetians decided to live there to keep themselves safe from invaders.</p></div>", "opts": ["(A) − (C) − (B)", "(B) − (A) − (C)", "(B) − (C) − (A)", "(C) − (A) − (B)", "(C) − (B) − (A)"], "en": true, "ans": 4, "ex": "이유 ▶ 어떻게, 왜 지었는지 궁금할 것 → (C) 왜: 침략자로부터 안전하려고 → (B) But 습지라 짓기 쉽지 않았다 → (A) So 나무 기둥 설치(어떻게).\n포인트 ▶ why(이유) → But(문제) → So(해결)", "ctx": "", "pts": 5, "words": [], "kos": [["You may wonder how and why they built the houses on the water.", "여러분은 어떻게 그리고 왜 그들이 물 위에 집을 지었는지 궁금할 것이다."], ["So they installed more than 10 million wooden poles in the ground.", "그래서 그들은 땅에 천만 개 이상의 나무 기둥들을 설치했다."], ["It is these wooden poles that support Venice to this day.", "지금까지 베니스를 지탱해 주고 있는 것은 바로 이 나무 기둥들이다."], ["But it was not easy for them to build their homes on this swampy surface.", "하지만 그들이 이 습지 위에 집을 짓는 것은 쉽지가 않았다."], ["The old Venetians decided to live there to keep themselves safe from invaders.", "옛 베니스인들은 침략자들로부터 자신들을 안전하게 지키기 위해 그곳에 살기로 결정했다."]]}, {"n": 12, "src": "본문", "stem": "(A), (B), (C)의 각 네모 안에서 어법에 맞는 표현으로 바르게 짝지은 것은?", "body": "<div class=\"wbox\"><p>I would sometimes hear my neighbor <b>(A)</b> [ call / to call ] me to come over for tea. … The people <b>(B)</b> [ living / lived ] in a tulou mostly have the same family name. … Living together in one building <b>(C)</b> [ keep / keeps ] them safe.</p></div><div class=\"wcols\">선택지 순서: (A) / (B) / (C)</div>", "opts": ["call / living / keeps", "to call / living / keeps", "call / lived / keeps", "call / living / keep", "to call / lived / keep"], "en": true, "ans": 0, "ex": "이유 ▶ (A) 지각동사 hear + 목적어 + 동사원형/-ing → call (B) 사람들이 '사는' 능동 → living (C) 주어는 동명사구(Living together ~) → 단수 keeps\n오답 ▶ 지각동사 뒤 to부정사 ❌ / lived는 수동 의미 / keep은 복수 동사라 동명사 주어(단수)와 맞지 않음\n포인트 ▶ 동명사 주어 → 단수 동사", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 13, "src": "본문", "stem": "글의 흐름으로 보아, 주어진 문장이 들어가기에 가장 알맞은 곳은?", "body": "<div class=\"wbox\"><p><b>My bedroom would be on the third or fourth floor.</b></p></div><div class=\"wbox\"><p>In a tulou, there are usually three to five floors. <span class=\"gap\">( ① )</span> The first floor is used for cooking and eating. <span class=\"gap\">( ② )</span> And people store food and tools on the second floor. <span class=\"gap\">( ③ )</span> Do you wonder where I would sleep? <span class=\"gap\">( ④ )</span> A tulou is like a village. <span class=\"gap\">( ⑤ )</span> The people living in a tulou mostly have the same family name.</p></div>", "opts": ["( ① ) 자리", "( ② ) 자리", "( ③ ) 자리", "( ④ ) 자리", "( ⑤ ) 자리"], "en": false, "ans": 3, "ex": "이유 ▶ '내가 어디서 잘지 궁금한가?'라는 질문 바로 뒤에 그 답(내 침실은 3·4층)이 와야 한다.\n오답 ▶ ①~③ 아직 잠잘 곳 질문이 나오기 전 ⑤ 마을 이야기로 넘어간 뒤", "ctx": "", "pts": 5, "words": [], "kos": [["My bedroom would be on the third or fourth floor.", "내 침실은 3층이나 4층에 있을 것이다."], ["In a tulou, there are usually three to five floors.", "토루는 대개 3층에서 5층으로 되어 있다."], ["The first floor is used for cooking and eating.", "1층은 요리하고 식사하는 데에 사용된다."], ["And people store food and tools on the second floor.", "그리고 사람들은 2층에 식량과 도구를 보관한다."], ["Do you wonder where I would sleep?", "내가 어디에서 잠을 잘지 궁금한가?"], ["A tulou is like a village.", "토루는 마을과 같다."], ["The people living in a tulou mostly have the same family name.", "토루에 사는 사람들은 대부분 같은 성(姓)을 가지고 있다."]]}, {"n": 14, "src": "본문", "stem": "다음 밑줄 친 house의 의미로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>Some large tulou can <u>house</u> up to 50 families.</p></div>", "opts": ["a building for people to live in", "to clean and decorate a room", "to sell a building to others", "to build a wall around a town", "to provide a place for people to live"], "en": true, "ans": 4, "ex": "이유 ▶ can 뒤의 house는 동사: ~에게 살 곳을 제공하다, 수용하다.\n오답 ▶ ① 명사 '집'의 뜻 — can 뒤에는 동사 ②·③·④ 다른 뜻\n포인트 ▶ 조동사 뒤 → 동사원형", "ctx": "", "pts": 5, "words": [], "kos": [["Some large tulou can house up to 50 families.", "몇몇 큰 토루는 50가구까지 수용할 수 있다."]]}, {"n": 15, "src": "문법", "stem": "다음 중 어법상 <u>틀린</u> 문장의 개수는?", "body": "<div class=\"wbox\"><p>(a) If I were a bird, I could fly to you.<br>(b) If he has a car, he would drive to work.<br>(c) If I lived in Alaska, I could go sledding all day.<br>(d) What would you do if you meet a famous singer?<br>(e) If it didn't rain, we would play soccer outside.</p></div>", "opts": ["1개", "2개", "3개", "4개", "5개"], "en": true, "ans": 1, "ex": "이유 ▶ 틀린 것 (b)·(d) 2개. (b) 주절 would → If절은 과거형 had (d) would ~ if → 과거형 met\n오답 ▶ (a) be동사는 주어와 관계없이 were ✔ (c)·(e) If + 과거형, could/would ✔", "ctx": "", "pts": 5, "words": [], "kos": [["If I were a bird, I would fly to you.", "만약 내가 새라면, 너에게 날아갈 텐데."], ["I wish I could live in Alaska. Then I could go sledding all day!", "난 알래스카에서 살았으면 좋겠어. 그러면 온종일 썰매 탈 수 있을 텐데!"], ["What would you do if you visited Spain?", "만약 네가 스페인을 방문한다면 너는 무엇을 할 거니?"]]}, {"n": 16, "src": "문법", "stem": "다음 문장과 의미가 같은 것은?", "body": "<div class=\"wbox\"><p>If I had a sled, I could go sledding.</p></div>", "opts": ["As I don't have a sled, I can't go sledding.", "As I have a sled, I can go sledding.", "As I didn't have a sled, I couldn't go sledding.", "If I don't have a sled, I can't go sledding.", "Though I don't have a sled, I can go sledding."], "en": true, "ans": 0, "ex": "이유 ▶ 가정법 과거 = 현재 사실의 반대 → 지금 썰매가 없어서 썰매를 탈 수 없다.\n오답 ▶ ② 반대 ③ 시제를 과거로 착각 ④ 조건문(직설법) ⑤ 뜻이 다름", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 17, "src": "문법", "stem": "다음 중 어법상 올바른 문장은?", "body": "", "opts": ["The thick walls keep me warmly in winter.", "This song always makes me happily.", "Regular exercise keeps you healthily.", "The sad news made her sadly.", "The mirrors would make the house almost invisible."], "en": true, "ans": 4, "ex": "이유 ▶ make + 목적어 + 형용사(invisible) ✔\n오답 ▶ ① warm ② happy ③ healthy ④ sad — 목적격 보어 자리에 부사 ❌\n포인트 ▶ 목적어의 상태를 설명 → 형용사", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 18, "src": "문법", "stem": "다음 우리말을 영어로 바르게 옮긴 것은?", "body": "<div class=\"wbox\"><p>지금까지 베니스를 지탱하는 것은 바로 이 나무 기둥들이다.</p></div>", "opts": ["It is these wooden poles what support Venice to this day.", "It is these wooden poles that support Venice to this day.", "It is these wooden poles that supports Venice to this day.", "That is these wooden poles it supports Venice to this day.", "It is these wooden poles support Venice to this day that."], "en": true, "ans": 1, "ex": "이유 ▶ It is + 강조할 말 + that ~ / 강조되는 말이 these wooden poles(복수) → support.\n오답 ▶ ① that 자리에 what ❌ ③ 복수 주어인데 supports ④·⑤ 어순 오류", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 19, "src": "본문", "stem": "7과 본문의 집과 그 특징이 바르게 연결되지 <u>않은</u> 것은?", "body": "", "opts": ["pueblo – has walls made of earth, straw, and water", "Venice – is supported by wooden poles", "tulou – can house up to 50 families", "tulou – has a flat roof to sleep on", "pueblo – is entered by climbing a ladder"], "en": true, "ans": 3, "ex": "이유 ▶ 평평한 지붕 위에서 잠을 자는 것은 푸에블로(The house has a flat roof. I would sometimes sleep up on the roof).\n오답 ▶ ①·②·③·⑤ 모두 본문 내용과 일치", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 20, "src": "본문", "stem": "본문 마지막 문장 <u>What is your home like?</u>를 쓴 의도로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>Homes are everywhere. But they are different all over the world. <u>What is your home like?</u></p></div>", "opts": ["독자가 좋아하는 집의 크기를 조사하려고", "독자의 집 주소를 물어보려고", "독자에게 자신의 집에 대해 생각해 보게 하려고", "세계에서 가장 좋은 집을 추천하려고", "집을 고치는 방법을 알려 주려고"], "en": true, "ans": 2, "ex": "이유 ▶ 세계의 집은 다 다르다 → '여러분의 집은 어떤가요?' = 독자 자신의 집을 떠올리게 하는 질문.\n오답 ▶ ①·②·④·⑤ 모두 글의 흐름(세계의 다양한 집 → 여러분의 집은?)과 관계없음\n포인트 ▶ What is ~ like? = ~은 어떠니?(모습·특징)", "ctx": "", "pts": 5, "words": [], "kos": [["But they are different all over the world.", "그러나 전 세계의 집은 다릅니다."]]}]}, {"id": "j7-3", "title": "7과 실전 변형 3회", "short": "3회", "school": "중3 지학사", "minutes": 30, "items": [{"n": 1, "src": "대화문", "stem": "주어진 말 다음에 이어질 대화의 순서로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>G: Have you heard from Julia? She's traveling in Türkiye, right?</p></div><div class=\"wbox\"><p><b>(A)</b> G: Yes, please. — B: Okay, take a look.<br><b>(B)</b> B: Yes, she sent me some pictures. Do you want to see them?<br><b>(C)</b> G: Oh, look at those cave houses! They look so unique, don't they? I wish I could try living there.</p></div>", "opts": ["(A) − (C) − (B)", "(B) − (A) − (C)", "(B) − (C) − (A)", "(C) − (A) − (B)", "(C) − (B) − (A)"], "en": true, "ans": 1, "ex": "이유 ▶ Julia 소식? → (B) 응, 사진을 보내왔어. 볼래? → (A) 응, 보여 줘 / 자, 봐 → (C) 저 동굴 집들 좀 봐!\n포인트 ▶ (A)의 Yes, please는 (B)의 Do you want to see them?에 대한 대답", "ctx": "", "pts": 5, "words": [], "kos": [["Wow, I wish I could try living there!", "와, 저곳에서 살아 봤으면 좋겠어!"]]}, {"n": 2, "src": "대화문", "stem": "According to the dialogue, which house would B most like to live in, and why?", "body": "<div class=\"wbox\"><p>A: Look at these houses. They look very natural.<br>B: Wow, I wish I could try living there!<br>A: Which house would you most like to live in?<br>B: I wish I could live in the stone house. It looks very strong.</p></div>", "opts": ["the stone house, because it looks very strong", "the stone house, because it looks very natural", "the tree house, because it looks very strong", "the cave house, because it looks unique", "the snow house, because it looks fun"], "en": true, "ans": 0, "ex": "이유 ▶ I wish I could live in the stone house. It looks very strong. ✔\n오답 ▶ ② natural은 집들 전체에 대한 A의 말 ③·④·⑤ 다른 집", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 3, "src": "대화문", "stem": "다음 중 짝지어진 대화가 <u>어색한</u> 것은?", "body": "", "opts": ["A: What would you do if you had a time machine? — B: I would go back to the Joseon Dynasty.", "A: I wish I could visit Spain. — B: Me too. I'd love to see Gaudí's buildings.", "A: Is it a kind of car? — B: Yes, it can move like a car.", "A: Would it be easy to live in the upside-down house? — B: No, it wouldn't.", "A: I wish I had a pet. — B: Oh, I'm glad that you have one."], "en": true, "ans": 4, "ex": "이유 ▶ I wish I had a pet = 지금 애완동물이 없다는 뜻. 그런데 '네가 하나 있어서 기쁘다'고 답하면 어색.\n오답 ▶ ① 가정 질문 → I would ~ ✔ ② 소망에 동의 ✔ ③ 질문에 맞는 답 ✔ ④ Would it ~? → No, it wouldn't ✔\n포인트 ▶ I wish + 과거형 = 현재 사실의 반대", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 4, "src": "대화문", "stem": "다음 대화의 빈칸에 들어갈 말로 알맞은 것은?", "body": "<div class=\"wbox\"><p>B: Isn't that the church Antoni Gaudí designed?<br>G: Yes, it is. It would be interesting to see how his design <span class=\"wblank\"></span> nature.</p></div>", "opts": ["inspired", "was inspiring", "inspires by", "is inspired", "was inspired by"], "en": true, "ans": 4, "ex": "이유 ▶ 디자인이 자연으로부터 '영감을 받았다' → 수동태 be inspired by. 이미 지어진 성당의 디자인 → 과거 was.\n오답 ▶ ① 능동(디자인이 자연에 영감을 줬다)이라 뜻이 반대 ② 진행형 능동 ③ 능동 + by ❌ ④ by가 없어 nature와 연결되지 않음", "ctx": "", "pts": 5, "words": [], "kos": [["Isn't that the church Antoni Gaudí designed?", "그 성당은 Antoni Gaudí가 설계한 거 아니니?"], ["Yes, it is. It would be interesting to see how his design was inspired by nature.", "응, 맞아. 그의 디자인이 어떻게 자연으로부터 영감을 받았는지 보는 것은 재미있을 거야."]]}, {"n": 5, "src": "대화문", "stem": "다음 대화를 읽고 답할 수 <u>없는</u> 질문은?", "body": "<div class=\"wbox\"><p>B: Will it snow today?<br>G: I have no idea. Why are you waiting for snow, Taeho?<br>B: I got a new sled for my birthday. I can't wait to test it out.<br>G: Let me check the weather. Umm, there will be no snow for a while.<br>B: I wish I could live in Alaska. Then I could go sledding all day!<br>G: No kidding! Alaska is a very cold place.<br>B: I think it would be fun. I want to build a snow house and stay there on vacation.</p></div>", "opts": ["What did Taeho get for his birthday?", "How long will Taeho stay in Alaska?", "Why is Taeho waiting for snow?", "Will it snow for a while?", "What does Taeho want to build?"], "en": true, "ans": 1, "ex": "이유 ▶ 태호가 알래스카에 얼마나 머물지는 나오지 않는다(소망일 뿐).\n오답 ▶ ① a new sled ③ 새 썰매를 시험해 보고 싶어서 ④ no snow for a while ⑤ a snow house", "ctx": "", "pts": 5, "words": [], "kos": [["I think it would be fun. I want to build a snow house and stay there on vacation.", "내 생각에는 재미있을 것 같아. 난 눈으로 만든 집을 짓고 방학 때 그곳에서 지내고 싶어."]]}, {"n": 6, "src": "대화문", "stem": "다음 빈칸에 들어갈 말로 알맞은 것은?", "body": "<div class=\"wbox\"><p>I would build a house <span class=\"wblank\"></span> is completely covered with mirrors.</p></div>", "opts": ["that", "what", "who", "where", "it"], "en": true, "ans": 0, "ex": "이유 ▶ 선행사 a house(사물) + 뒤에 주어가 빠진 절(is covered ~) → 주격 관계대명사 that(= which).\n오답 ▶ ② what은 선행사를 포함 ③ who는 사람 ④ where 뒤에는 완전한 절 ⑤ it을 쓰면 접속사 없이 절이 두 개", "ctx": "", "pts": 5, "words": [], "kos": [["I would build a house that is completely covered with mirrors.", "난 거울로 완전히 뒤덮인 집을 지을 거야."]]}, {"n": 7, "src": "본문", "stem": "다음 글의 ①~⑤ 중 전체 흐름과 관계없는 문장은?", "body": "<div class=\"wbox\"><p>If I lived in a pueblo, I would climb up a ladder to enter my house. ① There's a hidden opening on top of the house. ② If unwelcome visitors appeared, I would pull the ladder up to stop them from entering. ③ Ladders were first used by people in ancient Egypt. ④ The thick walls are made of earth, straw, and water. ⑤ The house has a flat roof.</p></div>", "opts": ["①번", "②번", "③번", "④번", "⑤번"], "en": false, "ans": 2, "ex": "이유 ▶ 푸에블로에 산다면 어떨지 상상하는 글. 사다리가 처음 쓰인 역사는 흐름과 관계없다.", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in a pueblo, I would climb up a ladder to enter my house.", "만약 내가 푸에블로에 산다면, 나는 집에 들어가기 위해 사다리를 오를 것이다."], ["There's a hidden opening on top of the house.", "집 꼭대기에는 숨겨진 구멍이 있다."], ["If unwelcome visitors appeared, I would pull the ladder up to stop them from entering.", "만약 반갑지 않은 방문객이 나타난다면 나는 사다리를 끌어 올려 그들이 들어오지 못하게 할 것이다."], ["The thick walls are made of earth, straw, and water.", "두꺼운 벽은 흙, 지푸라기, 물로 만들어져 있다."], ["The house has a flat roof.", "집에는 평평한 지붕이 있다."]]}, {"n": 8, "src": "본문", "stem": "다음 글의 내용을 한 문장으로 요약할 때, 빈칸 (A), (B)에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>If I lived in a pueblo, I would climb up a ladder to enter my house. There's a hidden opening on top of the house. If unwelcome visitors appeared, I would pull the ladder up to stop them from entering. The thick walls are made of earth, straw, and water. They would keep me cool in summer and warm in winter. The house has a flat roof. I would sometimes sleep up on the roof under the moon and stars.</p></div><div class=\"wsum\">The pueblo's <b>(A)</b> <span class=\"wblank\"></span> walls help keep the temperature inside <b>(B)</b> <span class=\"wblank\"></span> all year round.</div><div class=\"wcols\">선택지 순서: (A) / (B)</div>", "opts": ["thick / comfortable", "thin / comfortable", "flat / cold", "thick / dangerous", "hidden / hot"], "en": true, "ans": 0, "ex": "이유 ▶ (A) The thick walls (B) 여름엔 시원하게, 겨울엔 따뜻하게 → 일 년 내내 '쾌적하게(comfortable)'\n오답 ▶ thin은 반대 / flat은 지붕 / cold·hot은 한 계절만 / dangerous는 근거 없음", "ctx": "", "pts": 5, "words": [], "kos": [["If I lived in a pueblo, I would climb up a ladder to enter my house.", "만약 내가 푸에블로에 산다면, 나는 집에 들어가기 위해 사다리를 오를 것이다."], ["There's a hidden opening on top of the house.", "집 꼭대기에는 숨겨진 구멍이 있다."], ["If unwelcome visitors appeared, I would pull the ladder up to stop them from entering.", "만약 반갑지 않은 방문객이 나타난다면 나는 사다리를 끌어 올려 그들이 들어오지 못하게 할 것이다."], ["The thick walls are made of earth, straw, and water.", "두꺼운 벽은 흙, 지푸라기, 물로 만들어져 있다."], ["They would keep me cool in summer and warm in winter.", "그것들은 여름에는 시원하게, 겨울에는 따뜻하게 유지해 줄 것이다."], ["The house has a flat roof.", "집에는 평평한 지붕이 있다."], ["I would sometimes sleep up on the roof under the moon and stars.", "때때로 나는 달과 별들 아래의 지붕 위에서 잠을 잘 것이다."]]}, {"n": 9, "src": "본문", "stem": "다음 빈칸에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>At high tide, the water from the Adriatic Sea often rises and leaves the streets full of water. <span class=\"wblank\"></span>, I would be able to walk around the town through the raised walkways.</p></div>", "opts": ["Therefore", "For example", "In addition", "However", "As a result"], "en": true, "ans": 3, "ex": "이유 ▶ 거리가 물에 잠긴다(문제) ↔ 그래도 높은 통로로 걸어 다닐 수 있다 → 대조 However(그러나).\n오답 ▶ ①·⑤ 결과(그래서)가 아니라 반대 상황 ② 예시 아님 ③ 추가 아님", "ctx": "", "pts": 5, "words": [], "kos": [["At high tide, the water from the Adriatic Sea often rises and leaves the streets full of water.", "조수가 높을 때에는 아드리아해의 물이 자주 불어나 거리를 물로 가득 차게 한다."]]}, {"n": 10, "src": "본문", "stem": "다음 글의 내용과 일치하는 것은?", "body": "<div class=\"wbox\"><p>Venice is known as the \"floating city.\" In Venice, there are many colorful houses on the water. You may wonder how and why they built the houses on the water. The old Venetians decided to live there to keep themselves safe from invaders. But it was not easy for them to build their homes on this swampy surface. So they installed more than 10 million wooden poles in the ground. It is these wooden poles that support Venice to this day.</p></div>", "opts": ["베니스의 집들은 대부분 한 가지 색으로 칠해져 있다.", "베니스 사람들은 물고기를 잡기 위해 물 위에 살기 시작했다.", "옛 베니스인들은 습지 위에 집 짓기가 쉽지 않아 땅에 나무 기둥을 설치했다.", "오늘날 베니스는 콘크리트 기둥이 지탱하고 있다.", "나무 기둥은 백만 개 정도 설치되었다."], "en": true, "ans": 2, "ex": "이유 ▶ not easy ~ on this swampy surface. So they installed more than 10 million wooden poles ✔\n오답 ▶ ① colorful houses(색색의) ② 침략자로부터 안전하려고 ④ these wooden poles that support Venice to this day ⑤ 천만 개 이상(10 million)", "ctx": "", "pts": 5, "words": [], "kos": [["Venice is known as the \"floating city.\"", "베니스는 '떠 있는 도시'로 알려져 있다."], ["In Venice, there are many colorful houses on the water.", "베니스에는 물 위에 있는 색색의 건물들이 많다."], ["You may wonder how and why they built the houses on the water.", "여러분은 어떻게 그리고 왜 그들이 물 위에 집을 지었는지 궁금할 것이다."], ["The old Venetians decided to live there to keep themselves safe from invaders.", "옛 베니스인들은 침략자들로부터 자신들을 안전하게 지키기 위해 그곳에 살기로 결정했다."], ["But it was not easy for them to build their homes on this swampy surface.", "하지만 그들이 이 습지 위에 집을 짓는 것은 쉽지가 않았다."], ["So they installed more than 10 million wooden poles in the ground.", "그래서 그들은 땅에 천만 개 이상의 나무 기둥들을 설치했다."], ["It is these wooden poles that support Venice to this day.", "지금까지 베니스를 지탱해 주고 있는 것은 바로 이 나무 기둥들이다."]]}, {"n": 11, "src": "본문", "stem": "다음 글의 밑줄 친 (a)~(g) 중 어법상 <u>틀린</u> 것의 개수는?", "body": "<div class=\"wbox\"><p>I would sometimes hear my neighbor <span class=\"tag\">(a)</span><u>calling</u> me to come over for tea. In a tulou, there <span class=\"tag\">(b)</span><u>is</u> usually three to five floors. The first floor <span class=\"tag\">(c)</span><u>is used</u> for cooking and eating. Do you wonder where <span class=\"tag\">(d)</span><u>would I sleep</u>? The people <span class=\"tag\">(e)</span><u>living</u> in a tulou mostly <span class=\"tag\">(f)</span><u>has</u> the same family name. Living together in one building <span class=\"tag\">(g)</span><u>keeps</u> them safe.</p></div>", "opts": ["1개", "2개", "3개", "4개", "5개"], "en": true, "ans": 2, "ex": "이유 ▶ 틀린 것 (b)·(d)·(f) 3개. (b) three to five floors(복수) → are (d) 간접의문문 어순 → where I would sleep (f) 주어 The people(복수) → have\n오답 ▶ (a) hear + 목적어 + -ing ✔ (c) 층이 '사용되는' 수동 ✔ (e) 사람들이 '사는' 능동 ✔ (g) 동명사 주어 → 단수 ✔", "ctx": "", "pts": 5, "words": [], "kos": [["I would sometimes hear my neighbor calling me to come over for tea or dinner.", "때때로 나의 이웃이 차를 마시거나 저녁 식사를 하러 들르라고 나를 부르는 소리를 듣게 될 것이다."], ["In a tulou, there are usually three to five floors.", "토루는 대개 3층에서 5층으로 되어 있다."], ["The first floor is used for cooking and eating.", "1층은 요리하고 식사하는 데에 사용된다."], ["Do you wonder where I would sleep?", "내가 어디에서 잠을 잘지 궁금한가?"], ["The people living in a tulou mostly have the same family name.", "토루에 사는 사람들은 대부분 같은 성(姓)을 가지고 있다."], ["Living together in one building keeps them safe.", "한 건물에 함께 사는 것은 그들을 안전하게 지켜 준다."]]}, {"n": 12, "src": "본문", "stem": "토루에서의 생활을 가장 잘 나타내는 것은?", "body": "<div class=\"wbox\"><p>A tulou is like a village. The people living in a tulou mostly have the same family name. Some large tulou can house up to 50 families. They work together and share many things. Living together in one building keeps them safe.</p></div>", "opts": ["privacy and independence", "community and cooperation", "competition and conflict", "travel and adventure", "silence and loneliness"], "en": true, "ans": 1, "ex": "이유 ▶ 마을 같음, 같은 성, 50가구, 함께 일하고 나눔(work together and share), 함께 살아 안전 → 공동체와 협력.\n오답 ▶ ①·③·⑤ 반대 ④ 정글 대화의 주제", "ctx": "", "pts": 5, "words": [], "kos": [["A tulou is like a village.", "토루는 마을과 같다."], ["The people living in a tulou mostly have the same family name.", "토루에 사는 사람들은 대부분 같은 성(姓)을 가지고 있다."], ["Some large tulou can house up to 50 families.", "몇몇 큰 토루는 50가구까지 수용할 수 있다."], ["They work together and share many things.", "그들은 함께 일하고 많은 것을 공유한다."], ["Living together in one building keeps them safe.", "한 건물에 함께 사는 것은 그들을 안전하게 지켜 준다."]]}, {"n": 13, "src": "문법", "stem": "다음 중 두 문장의 의미가 서로 <u>다른</u> 것은?", "body": "", "opts": ["As I am not tall, I can't reach the shelf. = If I were tall, I could reach the shelf.", "If she had time, she would help us. = As she doesn't have time, she won't help us.", "I am sorry that I can't fly. = I wish I could fly.", "As it is raining, we can't go out. = If it weren't raining, we could go out.", "If I lived in Venice, I would take a gondola. = I live in Venice, so I take a gondola."], "en": true, "ans": 4, "ex": "이유 ▶ 가정법 과거(If I lived in Venice) = 실제로는 베니스에 살지 않는다. 오른쪽은 실제로 산다는 뜻이라 반대.\n오답 ▶ ①·②·④ 직설법 ↔ 가정법 과거 ✔ ③ I wish = I am sorry that ~ 못 해서 ✔", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 14, "src": "문법", "stem": "다음 중 어법상 올바른 문장끼리 바르게 짝지은 것은?", "body": "<div class=\"wbox\"><p>ⓐ If I were you, I would keep the window open.<br>ⓑ The thick walls would keep me coolly in summer.<br>ⓒ If he knew her number, he will call her.<br>ⓓ What would you do if you became a millionaire?<br>ⓔ The mirrors would make the house invisible.</p></div>", "opts": ["ⓐ, ⓑ", "ⓑ, ⓒ", "ⓐ, ⓓ", "ⓐ, ⓓ, ⓔ", "ⓒ, ⓓ, ⓔ"], "en": true, "ans": 3, "ex": "이유 ▶ 올바른 것 ⓐ·ⓓ·ⓔ.\n오답 ▶ ⓑ keep + 목적어 + 형용사 → cool ⓒ 가정법 과거 → would call\n포인트 ▶ ③은 ⓔ가 빠진 함정 — 올바른 것을 '모두' 담은 선택지!", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 15, "src": "문법", "stem": "다음 우리말을 영어로 바르게 옮긴 것은?", "body": "<div class=\"wbox\"><p>만약 내가 토루에 산다면, 나는 항상 집에 함께 놀 친구들이 있을 텐데.</p></div>", "opts": ["If I lived in a tulou, I would always have friends at home to play with.", "If I lived in a tulou, I would always have friends at home to play.", "If I live in a tulou, I would always have friends at home to play with.", "If I lived in a tulou, I will always have friends at home to play with.", "If I lived in a tulou, I would always had friends at home to play with."], "en": true, "ans": 0, "ex": "이유 ▶ 가정법 과거 + friends to play with(함께 놀 친구 — play with friends이므로 with 필요).\n오답 ▶ ② with 빠짐 ③ If절 현재형 ④ 주절 will ⑤ would 뒤 동사원형 have", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 16, "src": "문법", "stem": "다음 밑줄 친 to부정사와 쓰임이 같은 것은?", "body": "<div class=\"wbox\"><p>If unwelcome visitors appeared, I would pull the ladder up <u>to stop</u> them from entering.</p></div>", "opts": ["It was not easy for them to build their homes.", "I would always have friends to play with.", "The old Venetians decided to live there.", "I hope to visit Türkiye some day.", "Some people use ladders to enter their houses."], "en": true, "ans": 4, "ex": "이유 ▶ to stop = ~하기 위해(목적, 부사적 용법). 사다리를 이용하는 목적 to enter와 같다.\n오답 ▶ ① 진주어(명사적) ② 명사 friends를 꾸밈(형용사적) ③·④ 목적어(명사적)", "ctx": "", "pts": 5, "words": [], "kos": [["If unwelcome visitors appeared, I would pull the ladder up to stop them from entering.", "만약 반갑지 않은 방문객이 나타난다면 나는 사다리를 끌어 올려 그들이 들어오지 못하게 할 것이다."]]}, {"n": 17, "src": "문법", "stem": "다음 중 어법상 올바른 문장은?", "body": "", "opts": ["I saw her to dance on the stage.", "I heard someone call my name.", "He made me to clean my room.", "The news made us happily.", "I heard the birds sang in the tree."], "en": true, "ans": 1, "ex": "이유 ▶ 지각동사 hear + 목적어 + 동사원형(또는 -ing) ✔\n오답 ▶ ① saw her dance[dancing] ③ 사역 make + 동사원형 clean ④ happy ⑤ sing[singing]", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 18, "src": "본문", "stem": "주어진 문장 다음에 이어질 글의 순서로 가장 알맞은 것은?", "body": "<div class=\"wbox\"><p>Different people live in different houses.</p></div><div class=\"wbox\"><p><b>(A)</b> And others share their houses with many people.<br><b>(B)</b> Imagine you live in one of these houses. How would that change your life?<br><b>(C)</b> Some use ladders to enter their houses. Others live in houses on the water.</p></div>", "opts": ["(A) − (C) − (B)", "(B) − (A) − (C)", "(B) − (C) − (A)", "(C) − (A) − (B)", "(C) − (B) − (A)"], "en": true, "ans": 3, "ex": "이유 ▶ 다양한 집 → (C) Some ~, Others ~ → (A) And others ~ → (B) 이 집들 중 하나에 산다고 상상해 보라.\n포인트 ▶ Some → Others → (And) others 나열 / these houses는 앞에 나온 집들을 가리킴", "ctx": "", "pts": 5, "words": [], "kos": [["Different people live in different houses.", "다양한 사람들이 다양한 집에서 삽니다."], ["And others share their houses with many people.", "그리고 또 다른 사람들은 많은 사람과 함께 집을 공유합니다."], ["Imagine you live in one of these houses.", "여러분이 이 집들 중 하나에 산다고 상상해 보세요."], ["How would that change your life?", "여러분의 삶은 어떻게 바뀔까요?"], ["Some use ladders to enter their houses.", "몇몇 사람들은 집에 들어가기 위해 사다리를 이용합니다."], ["Others live in houses on the water.", "다른 사람들은 물 위에 있는 집에 삽니다."]]}, {"n": 19, "src": "본문", "stem": "7과 본문의 주제로 가장 알맞은 것은?", "body": "", "opts": ["why people should live with big families", "the dangers of living on the water", "the best kind of house to live in", "how houses reflect people's surroundings and ways of life", "how to design a house with mirrors"], "en": true, "ans": 3, "ex": "이유 ▶ 침입자를 막는 사다리, 기후에 맞는 두꺼운 벽, 침략을 피한 물 위의 집, 함께 사는 토루 → 집은 환경과 생활 방식을 반영.\n오답 ▶ ① 토루 한 부분 ② 위험이 주제가 아님 ③ 최고의 집을 고르지 않음 ⑤ 대화문 내용\n어휘 ▶ reflect 반영하다 · surroundings 환경", "ctx": "", "pts": 5, "words": [], "kos": []}, {"n": 20, "src": "본문", "stem": "7과 본문 전체를 한 문장으로 요약할 때, 빈칸 (A), (B)에 들어갈 말로 가장 알맞은 것은?", "body": "<div class=\"wsum\">People around the world live in <b>(A)</b> <span class=\"wblank\"></span> houses, and each home reflects the <b>(B)</b> <span class=\"wblank\"></span> of the people living in it.</div><div class=\"wcols\">선택지 순서: (A) / (B)</div>", "opts": ["similar / way of life", "different / family name", "different / way of life", "modern / language", "similar / hometown"], "en": true, "ans": 2, "ex": "이유 ▶ (A) Homes are everywhere. But they are different all over the world. → different (B) 사다리로 오르내리기, 곤돌라 통학, 이웃과 함께 사는 삶 → 생활 방식(way of life)\n오답 ▶ similar는 반대 / family name은 토루의 세부 / modern·language는 근거 없음", "ctx": "", "pts": 5, "words": [], "kos": []}]}];
